import sys, json, ast
from datetime import datetime

path = sys.argv[1]
mode = sys.argv[2] if len(sys.argv) > 2 else "flow"

entries = []
for line in sys.stdin:
    line = line.strip()
    if not line:
        continue
    try:
        d = json.loads(line)
    except Exception:
        continue
    entries.append(d)

def parse_msg(d):
    m = d.get("message")
    if isinstance(m, str):
        try:
            return ast.literal_eval(m)
        except Exception:
            return None
    return m

def ts(d):
    t = d.get("timestamp")
    if not t:
        return None
    try:
        return datetime.fromisoformat(t.replace("Z", "+00:00"))
    except Exception:
        return None

t0 = None
prev = None
rows = []
for d in entries:
    m = parse_msg(d)
    tt = ts(d)
    if tt and t0 is None:
        t0 = tt
    off = (tt - t0).total_seconds() if (tt and t0) else 0
    gap = (tt - prev).total_seconds() if (tt and prev) else 0
    if tt:
        prev = tt
    if not m:
        continue
    role = m.get("role") or d.get("type")
    content = m.get("content")
    if isinstance(content, str):
        content = [{"type": "text", "text": content}]
    if not isinstance(content, list):
        continue
    for c in content:
        if not isinstance(c, dict):
            continue
        ty = c.get("type")
        if ty == "text":
            txt = " ".join(c.get("text", "").split())
            if txt:
                rows.append((off, gap, role, "TEXT", txt))
        elif ty == "thinking":
            pass
        elif ty == "tool_use":
            nm = c.get("name")
            inp = c.get("input", {})
            desc = inp.get("command") or inp.get("file_path") or inp.get("pattern") or inp.get("prompt") or inp.get("query") or ""
            desc = " ".join(str(desc).split())
            rows.append((off, gap, role, "TOOL:" + str(nm), desc))
        elif ty == "tool_result":
            cc = c.get("content")
            s = ""
            if isinstance(cc, list):
                s = " ".join(x.get("text", "") for x in cc if isinstance(x, dict))
            elif isinstance(cc, str):
                s = cc
            s = " ".join(s.split())
            rows.append((off, gap, role, "RESULT", s))

if mode == "gaps":
    rows.sort(key=lambda r: -r[1])
    for off, gap, role, kind, txt in rows[:30]:
        print(f"[gap {gap:7.1f}s @t+{off:7.1f}] {kind}: {txt[:200]}")
else:
    lim = int(sys.argv[3]) if len(sys.argv) > 3 else 400
    for off, gap, role, kind, txt in rows:
        if kind == "RESULT":
            if gap < 20:
                continue
            print(f"t+{off:7.1f} (+{gap:5.1f}s) {kind}: {txt[:lim]}")
        elif kind == "TEXT":
            print(f"t+{off:7.1f} (+{gap:5.1f}s) {role.upper()} {kind}: {txt[:lim]}")
        else:
            print(f"t+{off:7.1f} (+{gap:5.1f}s) {kind}: {txt[:220]}")

